const fs = require('fs');
const path = require('path');

const dir = path.join(__dirname, 'assets', 'webapp');
let html = fs.readFileSync(path.join(dir, 'index.html'), 'utf8');
const css = fs.readFileSync(path.join(dir, 'style.css'), 'utf8');
const js = fs.readFileSync(path.join(dir, 'app.js'), 'utf8');

html = html.replace(
  '<link rel="stylesheet" href="css/style.css">',
  `<style>\n${css}\n</style>`
);
html = html.replace(
  '<script src="js/app.js"></script>',
  `<script>\n${js}\n</script>`
);

const out = `// AUTO-GENERATED by build-webview-bundle.js — do not edit directly.\n// Re-run "node build-webview-bundle.js" after changing files in assets/webapp/.\nexport const LEDGER_HTML = ${JSON.stringify(html)};\n`;
fs.writeFileSync(path.join(__dirname, 'webviewContent.js'), out);
console.log('Wrote webviewContent.js, length:', out.length);
